import os
import shutil
import uuid

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return os.path.join(BACKUP_DIR, f"backup_{uuid.uuid4().hex}")


def _clean_directory(directory, errors):
    try:
        entries = list(os.scandir(directory))
    except Exception as exc:
        errors.append(f"Failed to inspect directory {directory}: {exc}")
        return

    for entry in entries:
        path = entry.path
        try:
            if entry.is_symlink() or entry.is_file(follow_symlinks=False):
                os.unlink(path)
            elif entry.is_dir(follow_symlinks=False):
                shutil.rmtree(path)
            else:
                os.unlink(path)
        except Exception as exc:
            errors.append(f"Failed to remove {path}: {exc}")


def task_func(directory):
    """
    Create a backup of `directory` and then clean its contents.

    Returns:
        tuple: (backup_directory_path, errors)
            backup_directory_path (str): Path to the created backup directory.
            errors (list): List of error messages, empty if operation succeeded.
    """
    errors = []
    backup_dir = get_unique_backup_dir()

    if not os.path.exists(directory):
        errors.append(f"Source directory does not exist: {directory}")
        return backup_dir, errors

    if not os.path.isdir(directory):
        errors.append(f"Source path is not a directory: {directory}")
        return backup_dir, errors

    try:
        os.makedirs(BACKUP_DIR, exist_ok=True)
    except Exception as exc:
        errors.append(f"Failed to prepare backup base directory {BACKUP_DIR}: {exc}")
        return backup_dir, errors

    try:
        shutil.copytree(directory, backup_dir)
    except Exception as exc:
        errors.append(f"Failed to create backup at {backup_dir}: {exc}")
        try:
            if os.path.exists(backup_dir):
                shutil.rmtree(backup_dir)
        except Exception as cleanup_exc:
            errors.append(f"Failed to remove incomplete backup {backup_dir}: {cleanup_exc}")
        return backup_dir, errors

    _clean_directory(directory, errors)
    return backup_dir, errors
